using System;
using System.Collections.Generic;
using System.Linq;
using ManagerServer.Model.Enums;
using ManagerServer.Globalization;
using System.Text;
using System.IO;
using ManagerServer.Model;
using System.Reflection;
using ManagerServer.Model.Attributes;
using ManagerServer.Model.Obsolete;
using System.Threading.Tasks;

namespace ManagerServer
{
    public static partial class Upgrade
    {
        private static async Task<IEnumerable<Model.Object>> Upgrade164(Orm.SQLiteConnection objects, IProgress<Tuple<int, int>> progress)
        {
            await Task.CompletedTask;
            var pdfTemplate = objects.OfType<ManagerServer.Model.Obsolete.Obsolete32.PdfTemplate32>().SingleOrDefault(x => x.Key == ManagerServer.Model.Object.GetGuidByType(typeof(ManagerServer.Model.Obsolete.Obsolete32.PdfTemplate32)));
            if (pdfTemplate == null) return null;
            if (pdfTemplate.Value == Guid.Empty) return null;

            var list = new List<Model.Object>();

            if (pdfTemplate.Value == new Guid("062e100249dc4b4cb1ecacee7b762b54"))
            {
                var base64 = "";
                list.Add(new ManagerServer.Model.CustomTheme() { Key = ManagerServer.Model.Object.GetGuidByType(typeof(ManagerServer.Model.CustomTheme)), Template = System.Text.UTF8Encoding.UTF8.GetString(Convert.FromBase64String(base64)), Name = "Custom template" });
            }
            else if (pdfTemplate.Value == new Guid("8cb7456d61a54d1cb6ca8dea400a5bfe"))
            {
                var base64 = "";
                list.Add(new ManagerServer.Model.CustomTheme() { Key = ManagerServer.Model.Object.GetGuidByType(typeof(ManagerServer.Model.CustomTheme)), Template = System.Text.UTF8Encoding.UTF8.GetString(Convert.FromBase64String(base64)), Name = "Custom template" });
            }
            else if (pdfTemplate.Value == new Guid("bc8e1ba45ee04988ad7ff0db6c6fa1b4"))
            {
                var base64 = "";
                list.Add(new ManagerServer.Model.CustomTheme() { Key = ManagerServer.Model.Object.GetGuidByType(typeof(ManagerServer.Model.CustomTheme)), Template = System.Text.UTF8Encoding.UTF8.GetString(Convert.FromBase64String(base64)), Name = "Custom template" });
            }
            else
            {
                var customTheme = objects.OfType<ManagerServer.Model.Obsolete.Obsolete32.CustomTheme32>().SingleOrDefault(x => x.Key == pdfTemplate.Value);
                if (customTheme == null) return null;
                if (string.IsNullOrWhiteSpace(customTheme.Definition)) return null;

                list.Add(new ManagerServer.Model.CustomTheme() { Key = ManagerServer.Model.Object.GetGuidByType(typeof(ManagerServer.Model.CustomTheme)), Template = customTheme.Definition, Name = customTheme.Name });
            }

            return list;
        }
    }
}
